SELECT usuario_id, fecha, monto
FROM `mi-proyecto.mi_dataset.pedidos`
QUALIFY ROW_NUMBER() OVER (PARTITION BY usuario_id ORDER BY fecha DESC) = 1;

SELECT pedido_id, item
FROM `mi-proyecto.mi_dataset.pedidos`,
  UNNEST(items) AS item;

SELECT *
FROM (
  SELECT categoria, mes, monto
  FROM `mi-proyecto.mi_dataset.ventas`
)
PIVOT (SUM(monto) FOR mes IN ('Ene', 'Feb', 'Mar'));

CREATE TABLE `mi-proyecto.mi_dataset.usuarios` (
  id INT64,
  nombre STRING,
  email STRING,
  creado_en TIMESTAMP
);

CREATE TABLE `mi-proyecto.mi_dataset.eventos`
PARTITION BY DATE(creado_en) AS
SELECT * FROM `mi-proyecto.mi_dataset.eventos_staging`;

CREATE VIEW `mi-proyecto.mi_dataset.ventas_2026` AS
SELECT * FROM `mi-proyecto.mi_dataset.ventas`
WHERE EXTRACT(YEAR FROM fecha) = 2026;

-- Caro: lee TODAS las columnas aunque uses pocas
SELECT * FROM `mi-proyecto.mi_dataset.ventas` WHERE categoria = 'ropa';

-- Mejor: solo las columnas que necesitas
SELECT id, monto, fecha FROM `mi-proyecto.mi_dataset.ventas` WHERE categoria = 'ropa';

SELECT *
FROM ML.PREDICT(
  MODEL `mi-proyecto.mi_dataset.modelo_precio`,
  (SELECT metros_cuadrados, habitaciones, antiguedad
   FROM `mi-proyecto.mi_dataset.propiedades_nuevas`)
);

CREATE OR REPLACE MODEL `mi-proyecto.mi_dataset.forecast_ventas`
OPTIONS (model_type = 'ARIMA_PLUS', time_series_timestamp_col = 'fecha', time_series_data_col = 'ventas') AS
SELECT fecha, ventas FROM `mi-proyecto.mi_dataset.ventas_diarias`;

SELECT *
FROM ML.FORECAST(MODEL `mi-proyecto.mi_dataset.forecast_ventas`, STRUCT(30 AS horizon));

SELECT ml_generate_text_result
FROM ML.GENERATE_TEXT(
  MODEL `mi-proyecto.mi_dataset.modelo_gemini`,
  (SELECT CONCAT('Resume esta reseña: ', texto) AS prompt
   FROM `mi-proyecto.mi_dataset.reseñas`)
);

SELECT *
FROM ML.GENERATE_EMBEDDING(
  MODEL `mi-proyecto.mi_dataset.modelo_embeddings`,
  (SELECT texto AS content FROM `mi-proyecto.mi_dataset.documentos`)
);

DECLARE umbral INT64 DEFAULT 1000;

IF (SELECT COUNT(*) FROM `mi-proyecto.mi_dataset.ventas`) > umbral THEN
  SELECT 'Hay muchas ventas' AS mensaje;
ELSE
  SELECT 'Volumen normal' AS mensaje;
END IF;

CREATE OR REPLACE PROCEDURE `mi-proyecto.mi_dataset.ventas_por_categoria`(categoria_in STRING)
BEGIN
  SELECT categoria, SUM(monto) AS total
  FROM `mi-proyecto.mi_dataset.ventas`
  WHERE categoria = categoria_in
  GROUP BY categoria;
END;

CALL `mi-proyecto.mi_dataset.ventas_por_categoria`('electrónica');
